import * as React from "react"

function CallForAction({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="call-for-action"
      className={className}
      {...props}
    >
      <div className="text-center">
          <h1 className="text-3xl font-extrabold tracking-normal text-gray-900 sm5xl md5xl md">
              <span className="block">Focus on creative</span>
          </h1>
          <p
              className="max-w-sm mx-auto mt-1 font-normal text-gray-500 text- sm5 sm md5 md sm2xl md2xl">
              Create ad previews with fewer steps so you can focus on what you do best.</p>
          <div className="max-w-md mx-auto mt-3 sm sm md6">
              <div className="rounded-full shadow">
                  <button type="button" className="flex items-center justify-center w-full px-8 py-3 text-base font-normal text-white bg-teal-400 border border-transparent rounded-full text-md hover300 md4 md2xl md10">Start for free</button>
              </div>
          </div>
      </div>
    </div>
  )
}

export { CallForAction }
